/**
 * @fileoverview A package only the host imports (#717): it runs what it is given.
 * @module api_tests/api_test_host_record_leaf/node_modules/host-pkg
 */

/**
 * Run a function.
 * @param {() => unknown} fn - The function.
 * @returns {unknown} What it returned.
 * @example
 * callThrough(() => 1); // 1
 */
export function callThrough(fn) {
	return fn();
}
